using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;

namespace ShareMeRowell {
    public sealed class StudioInput:Panel {
        public StudioInput(TextBox input){DoubleBuffered=true;BackColor=Palette.Page;Size=new Size(300,38);Padding=new Padding(11,8,11,7);input.BorderStyle=BorderStyle.None;input.BackColor=Palette.Raised;input.ForeColor=Palette.Text;input.Dock=DockStyle.Fill;input.Enter+=(s,e)=>Invalidate();input.Leave+=(s,e)=>Invalidate();Controls.Add(input);}
        protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(BackColor);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(new RectangleF(1,1,Width-3,Height-3),8))using(var fill=new SolidBrush(Palette.Raised))using(var border=new Pen(ContainsFocus?Palette.Mint:Palette.Border,1)){e.Graphics.FillPath(fill,path);e.Graphics.DrawPath(border,path);}}
    }
    public sealed class StudioScroll:UserControl {
        public readonly FlowLayoutPanel Content=new FlowLayoutPanel();
        readonly Panel viewport=new Panel();readonly SlimScroll bar;bool layingOut;int offset,maximum;
        public int ScrollOffset{get{return offset;}} public int MaximumOffset{get{return maximum;}}
        public StudioScroll(){BackColor=Palette.Page;DoubleBuffered=true;viewport.Dock=DockStyle.Fill;viewport.BackColor=BackColor;Controls.Add(viewport);bar=new SlimScroll(this){Dock=DockStyle.Right,Width=12};Controls.Add(bar);Content.FlowDirection=FlowDirection.TopDown;Content.WrapContents=false;Content.AutoScroll=false;Content.BackColor=BackColor;Content.Margin=Padding.Empty;viewport.Controls.Add(Content);viewport.Resize+=(s,e)=>RefreshContent();Content.ControlAdded+=(s,e)=>{HookWheel(e.Control);RefreshContent();};Content.ControlRemoved+=(s,e)=>RefreshContent();Content.Layout+=(s,e)=>RefreshContent();MouseWheel+=Wheel;viewport.MouseWheel+=Wheel;Content.MouseWheel+=Wheel;}
        void HookWheel(Control control){if(!(control is ComboBox))control.MouseWheel+=Wheel;foreach(Control child in control.Controls)HookWheel(child);control.ControlAdded+=(s,e)=>HookWheel(e.Control);}
        void Wheel(object sender,MouseEventArgs e){var handled=e as HandledMouseEventArgs;if(handled!=null&&handled.Handled)return;ScrollTo(offset-e.Delta/120*64);if(handled!=null)handled.Handled=true;}
        public void ScrollTo(int value){offset=Math.Max(0,Math.Min(maximum,value));Content.Top=-offset;bar.Invalidate();}
        public void RefreshContent(){if(layingOut||IsDisposed)return;layingOut=true;try{int width=Math.Max(40,viewport.ClientSize.Width);if(Content.Width!=width)Content.Width=width;var preferred=Content.GetPreferredSize(new Size(width,0));Content.Height=Math.Max(viewport.Height,preferred.Height);maximum=Math.Max(0,Content.Height-viewport.Height);ScrollTo(offset);bar.Enabled=maximum>0;bar.Invalidate();}finally{layingOut=false;}}
        protected override void OnResize(EventArgs e){base.OnResize(e);RefreshContent();}
        sealed class SlimScroll:Control {
            readonly StudioScroll owner;bool hover,dragging;int anchor,initial;
            public SlimScroll(StudioScroll scroll){owner=scroll;DoubleBuffered=true;Cursor=Cursors.Hand;AccessibleName="Scroll content";AccessibleRole=AccessibleRole.ScrollBar;TabStop=true;}
            Rectangle Thumb{get{int height=owner.maximum==0?Height:Math.Max(32,(int)((long)Height*owner.viewport.Height/Math.Max(1,owner.Content.Height)));return new Rectangle(4,owner.maximum==0?0:(Height-height)*owner.offset/owner.maximum,4,height);}}
            protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Palette.Page);if(!Enabled)return;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;var t=Thumb;using(var path=Palette.Round(t,2))using(var brush=new SolidBrush(dragging||hover?Palette.Mint:Color.FromArgb(78,88,108)))e.Graphics.FillPath(brush,path);}
            protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
            protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;if(new Rectangle(0,Thumb.Top,Width,Thumb.Height).Contains(e.Location)){dragging=true;anchor=e.Y;initial=owner.offset;Capture=true;}else owner.ScrollTo(owner.offset+(e.Y<Thumb.Top?-1:1)*owner.viewport.Height);Invalidate();}
            protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging)owner.ScrollTo(initial+(e.Y-anchor)*owner.maximum/Math.Max(1,Height-Thumb.Height));}
            protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;Invalidate();base.OnMouseUp(e);}
            protected override bool IsInputKey(Keys keyData){return keyData==Keys.Up||keyData==Keys.Down||keyData==Keys.PageUp||keyData==Keys.PageDown||keyData==Keys.Home||keyData==Keys.End||base.IsInputKey(keyData);}
            protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(e.KeyCode==Keys.Home)owner.ScrollTo(0);else if(e.KeyCode==Keys.End)owner.ScrollTo(owner.maximum);else if(e.KeyCode==Keys.Up||e.KeyCode==Keys.Down)owner.ScrollTo(owner.offset+(e.KeyCode==Keys.Up?-48:48));else if(e.KeyCode==Keys.PageUp||e.KeyCode==Keys.PageDown)owner.ScrollTo(owner.offset+(e.KeyCode==Keys.PageUp?-1:1)*owner.viewport.Height);}
        }
    }
    public sealed class CharacterTile:Button {
        public readonly int RoleIndex;int earnedLevel;HeroProfile profile;Bitmap image;public bool Selected;public bool Equipped;
        public CharacterTile(int role,int level,HeroProfile source){RoleIndex=role;earnedLevel=level;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Palette.Page;DoubleBuffered=true;Cursor=Cursors.Hand;Size=new Size(180,196);Margin=new Padding(0,0,10,10);AccessibleName="Preview "+Adventure.Roles[role];UpdateProfile(source);}
        public void UpdateProfile(HeroProfile source){if(image!=null&&Adventure.IsFixedDesign(RoleIndex))return;profile=source.Copy();profile.Role=RoleIndex;if(image!=null)image.Dispose();image=PortraitCatalog.Thumbnail(profile,earnedLevel,Math.Max(earnedLevel,Adventure.RoleLevels[RoleIndex]));Invalidate();}
        public void UpdateLevel(int level){if(earnedLevel==level)return;earnedLevel=level;if(image!=null){image.Dispose();image=null;}UpdateProfile(profile);}
        protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(new RectangleF(1,1,Width-3,Height-3),12))using(var brush=new SolidBrush(Selected?Palette.Raised:Palette.Card))using(var pen=new Pen(Selected?Palette.Mint:Palette.Border,Selected?1.6f:1)){g.FillPath(brush,path);g.DrawPath(pen,path);}var small=Palette.Font(8);var title=Palette.Font(9,true);try{TextRenderer.DrawText(g,Equipped?"EQUIPPED":RoleIndex==0?"YOUR AVATAR":Adventure.IsFixedDesign(RoleIndex)?"SIGNATURE":"CLASSIC",small,new Rectangle(12,10,Width-24,18),Equipped?Palette.Mint:Palette.Muted,TextFormatFlags.NoPrefix);if(image!=null)g.DrawImage(image,new Rectangle((Width-112)/2,30,112,112));TextRenderer.DrawText(g,RoleIndex==0?"Your avatar":Adventure.Roles[RoleIndex],title,new Rectangle(8,144,Width-16,23),Palette.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);TextRenderer.DrawText(g,RoleIndex==0?"Customizable":earnedLevel>=Adventure.RoleLevels[RoleIndex]?"Unlocked":"Unlock at Lv "+Adventure.RoleLevels[RoleIndex],small,new Rectangle(8,170,Width-16,18),earnedLevel>=Adventure.RoleLevels[RoleIndex]?Palette.Mint:Palette.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.NoPrefix);}finally{small.Dispose();title.Dispose();}if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(5,5,Width-10,Height-10));}
        protected override void Dispose(bool disposing){if(disposing&&image!=null)image.Dispose();base.Dispose(disposing);}
    }
    public sealed class StyleOption:Button {
        public bool Selected;public Color? Swatch;public HeroProfile HairPreview;bool hover;
        public StyleOption(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;Cursor=Cursors.Hand;DoubleBuffered=true;BackColor=Palette.Page;Size=new Size(90,36);Margin=new Padding(0,0,8,8);Font=Palette.Font(9);}
        protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=false;Invalidate();base.OnMouseLeave(e);}
        protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(BackColor);g.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Palette.Round(new RectangleF(1,1,Width-3,Height-3),Swatch.HasValue?Height/2:9))using(var brush=new SolidBrush(Swatch??(Selected||hover?Palette.Raised:Palette.Card)))using(var pen=new Pen(Selected?Palette.Mint:Palette.Border,Selected?2f:1)){g.FillPath(brush,path);g.DrawPath(pen,path);}if(HairPreview!=null){using(var head=PortraitCatalog.Thumbnail(HairPreview,1,1)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(head,new Rectangle((Width-48)/2,5,48,42),new Rectangle(18,0,76,62),GraphicsUnit.Pixel);}TextRenderer.DrawText(g,Text,Font,new Rectangle(2,49,Width-4,22),Selected?Palette.Mint:Palette.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.NoPrefix);}else if(!Swatch.HasValue)TextRenderer.DrawText(g,Text,Font,ClientRectangle,Selected?Palette.Mint:Palette.Text,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);else if(Selected)TextRenderer.DrawText(g,"✓",Font,ClientRectangle,Color.FromArgb(Swatch.Value.GetBrightness()>.55?15:250,Swatch.Value.GetBrightness()>.55?20:250,Swatch.Value.GetBrightness()>.55?30:250),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(g,new Rectangle(5,5,Width-10,Height-10));}
    }
}
